package ama.task;
import ama.contract.OutboxContracts.*;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
class OutboxConsumerIT {
 TaskFixture f;String consumer;JdbcOutboxConsumer c;AtomicBoolean fail;
 @BeforeEach void setup(){f=new TaskFixture();consumer="TEST_"+UUID.randomUUID();fail=new AtomicBoolean();c=new JdbcOutboxConsumer(f.source,f.outbox,Map.of(consumer,new OutboxConsumerPolicy(){
  public void prelockDomains(List<OutboxEvent> events){var ids=events.stream().map(e->e.event().subject().id()).distinct().sorted().toList();for(var id:ids)f.fences.lock(new ama.contract.TaskContracts.SubjectRef("MEETING",id),false).orElseThrow();for(var id:ids)f.j.queryForObject("SELECT id FROM meeting WHERE id=? FOR UPDATE",String.class,id);}
  public void applyToPrelockedDomains(List<OutboxEvent> events){for(var event:events)f.j.update("UPDATE meeting SET materials_pending=1 WHERE id=?",event.event().subject().id());if(fail.get())throw new IllegalStateException("local consumer rollback");}
 }));c.register(consumer);f.queue().enqueue(f.spec());}
 @Test void prefixAndEffectsCommitTogetherAndDuplicateCannotSkip(){var l=c.claim(consumer,"first");assertTrue(l.isPresent());var page=c.read(l.orElseThrow(),2);assertEquals(2,page.size());assertFalse(c.apply(l.orElseThrow(),List.of(page.getLast())));assertTrue(c.apply(l.orElseThrow(),List.of(page.getFirst())));assertFalse(c.apply(l.orElseThrow(),List.of(page.getFirst())));assertEquals(page.getFirst().sequence(),f.j.queryForObject("SELECT `cursor` FROM outbox_consumer WHERE consumer_id=?",Long.class,consumer));assertEquals(1,f.j.queryForObject("SELECT materials_pending FROM meeting WHERE id=?",Integer.class,page.getFirst().event().subject().id()));}
 @Test void rollbackDoesNotAdvanceAndExpiredEpochCannotAcknowledge(){var l=c.claim(consumer,"old");assertTrue(l.isPresent());var page=c.read(l.orElseThrow(),1);f.j.update("UPDATE meeting SET materials_pending=0 WHERE id=?",page.getFirst().event().subject().id());fail.set(true);assertThrows(IllegalStateException.class,()->c.apply(l.orElseThrow(),page));assertEquals(0,f.j.queryForObject("SELECT `cursor` FROM outbox_consumer WHERE consumer_id=?",Long.class,consumer));assertEquals(0,f.j.queryForObject("SELECT materials_pending FROM meeting WHERE id=?",Integer.class,page.getFirst().event().subject().id()));fail.set(false);f.j.update("UPDATE outbox_consumer SET expires_at=UTC_TIMESTAMP(6)-INTERVAL 1 SECOND WHERE consumer_id=?",consumer);var fresh=c.claim(consumer,"new");assertTrue(fresh.isPresent());assertFalse(c.renew(l.orElseThrow()));assertFalse(c.apply(l.orElseThrow(),page));assertTrue(c.apply(fresh.orElseThrow(),page));}
}
